import React, { useState } from "react";
import { supabase } from "./supabaseClient";

function Login(props) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleLogin(e) {
    e.preventDefault();
    setLoading(true);
    setError("");
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    setLoading(false);
    if (error) {
      setError("بيانات الدخول غير صحيحة!");
    } else {
      // ✅ أغلق نافذة تسجيل الدخول بعد النجاح
      if (props.onClose) props.onClose();
    }
  }

  return (
    <div style={{ ...modalStyle }}>
      <form onSubmit={handleLogin} style={{ ...formStyle }}>
        <h2>تسجيل الدخول</h2>
        <input
          type="email"
          placeholder="الإيميل"
          value={email}
          onChange={e => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="كلمة المرور"
          value={password}
          onChange={e => setPassword(e.target.value)}
          required
        />
        <button type="submit" disabled={loading}>
          {loading ? "جاري الدخول..." : "دخول"}
        </button>
        {error && <div style={{ color: "red" }}>{error}</div>}
      </form>
      {/* زر إغلاق اختياري */}
      {props.onClose && (
        <button onClick={props.onClose} style={{ marginTop: 10 }}>إغلاق</button>
      )}
    </div>
  );
}

// أضف أي ستايلات تريدها للنافذة/form (يمكنك تخصيصها)
const modalStyle = {
  position: "fixed", top: 0, left: 0, width: "100vw", height: "100vh",
  background: "rgba(0,0,0,0.25)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 2000
};
const formStyle = {
  background: "#fff", padding: 24, borderRadius: 16, minWidth: 320
};

export default Login;
