import React, { useState, useEffect } from "react";
import { supabase } from "./supabaseClient";
import Login from "./Login";
import Papa from "papaparse";
import * as XLSX from "xlsx";

// ألوان للرسومات البيانية
const COLORS = ["#8884d8", "#82ca9d", "#ffc658", "#ffb86c", "#5aa9fa", "#fa5a7d", "#16a085"];

function App() {
  const [user, setUser] = useState(null);
  const [showLogin, setShowLogin] = useState(false);
  const [data, setData] = useState([]);
  const [summary, setSummary] = useState({});
  const [visits, setVisits] = useState(0);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  // ---- auth logic ----
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setUser(data?.session?.user || null);
    });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user || null);
    });
    return () => listener?.subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      fetchLatestReport();
    } else {
      setLoading(false);
    }
  }, [user]);

  // تحميل أحدث تقرير محفوظ
  async function fetchLatestReport() {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("order_reports")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(1);

      if (data && data.length) {
        const report = data[0];
        setData(report.report_data.rows || []);
        let summaryObj = report.report_data.summary;
        if (typeof summaryObj === "string") {
          try {
            summaryObj = JSON.parse(summaryObj);
          } catch {
            summaryObj = {};
          }
        }
        setSummary(summaryObj || {});
        setVisits(report.visits || 0);
      } else {
        setData([]);
        setSummary({});
        setVisits(0);
      }
    } catch (err) {
      console.error("Error fetching report:", err);
    } finally {
      setLoading(false);
    }
  }

  // رفع ملف جديد (CSV أو Excel)
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const fileName = file.name.toLowerCase();
    if (fileName.endsWith(".csv")) {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: function (results) {
          processAndUploadReport(results.data, file.name);
        },
      });
    } else if (fileName.endsWith(".xlsx") || fileName.endsWith(".xls")) {
      const reader = new FileReader();
      reader.onload = (evt) => {
        const data = new Uint8Array(evt.target.result);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });
        processAndUploadReport(jsonData, file.name);
      };
      reader.readAsArrayBuffer(file);
    } else {
      alert("الرجاء رفع ملف CSV أو Excel فقط!");
    }
  };

  // --- معالجة ورفع التقرير ---
  async function processAndUploadReport(rows, fileName) {
    setUploading(true);

    // =========================
    //      التحليلات المطلوبة
    // =========================
    let totalSales = 0;
    const paymentMethods = {};
    const shippingInfoTable = {};
    const orderTypes = { "قوقل كروم": 0, "ايفون": 0, "اندرويد": 0 };
    const regionOrders = {};
    const productOrders = {};

    // تحليل البيانات
    rows.forEach(row => {
      // إجمالي المبيعات
      let value = (row["teest"] || row["Grand Total (Base)"] || row["Grand Total (Purchased)"] || "0")
        .toString()
        .replace(/,/g, "")
        .trim();
      let total = parseFloat(value);
      if (!isNaN(total)) totalSales += total;

      // طرق الدفع
      let pay = (row["Payment Method"] || "").toLowerCase();
      let payLabel = "غير معروف";
      if (pay.includes("madfu")) payLabel = "مدفوع";
      else if (pay.includes("credit") || pay.includes("debit") || pay.includes("apple")) payLabel = "بطاقة ائتمانية";
      else if (pay.includes("tamara")) payLabel = "تمارا";
      else if (pay.includes("pay in 4") || pay.includes("tabby") || pay.includes("تابي")) payLabel = "تابي";
      else if (pay) payLabel = row["Payment Method"];
      paymentMethods[payLabel] = (paymentMethods[payLabel] || 0) + 1;

      // وسيلة الشحن
      let shipping = row["Shipping Information"] || "";
      if (shipping) shippingInfoTable[shipping] = (shippingInfoTable[shipping] || 0) + 1;

      // نوع الطلب
      let type = (row["Order Type"] || "").toLowerCase();
      if (type.includes("web")) orderTypes["قوقل كروم"] += 1;
      else if (type.includes("ios")) orderTypes["ايفون"] += 1;
      else if (type.includes("android")) orderTypes["اندرويد"] += 1;

      // المدن (region)
      let region = (row["Region"] || row[" Region"] || "").trim();
      if (region) regionOrders[region] = (regionOrders[region] || 0) + 1;

      // المنتجات (Product Details)
      let details = row["Product Details"] || "";
      const items = details.split("|").filter((x) => x.startsWith("Name:"));
      items.forEach((item) => {
        let name = item.replace("Name:", "").trim();
        if (name) productOrders[name] = (productOrders[name] || 0) + 1;
      });
    });

    const reportSummary = {
      totalSales,
      paymentMethods,
      shippingInfoTable,
      orderTypes,
      regionOrders,
      productOrders
    };

    // رفع البيانات في supabase
    const { error } = await supabase.from("order_reports").insert([
      {
        report_data: { rows, summary: reportSummary },
        visits,
        report_file_name: fileName,
      },
    ]);
    setUploading(false);
    if (error) {
      alert("حدث خطأ أثناء رفع التقرير: " + error.message);
    } else {
      fetchLatestReport();
      alert("تم رفع التقرير بنجاح!");
    }
  }

  // ----- تجهيز البيانات للعرض -----
  const paymentData = Object.entries(summary.paymentMethods || {}).map(([name, value]) => ({ name, value }));
  const shippingTable = Object.entries(summary.shippingInfoTable || {}).map(([name, value]) => ({ name, value }));
  const topProducts = Object.entries(summary.productOrders || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([name, orders]) => ({ name, orders }));
  const topRegions = Object.entries(summary.regionOrders || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, orders]) => ({ name, orders }));

  // Pie Chart label
  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return (
      <text x={x} y={y} fill="#111" fontWeight="bold" fontSize={24} textAnchor="middle" dominantBaseline="middle">
        {(percent * 100).toFixed(0)}%
      </text>
    );
  };

  return (
    <div style={{ fontFamily: "Tahoma, Arial, sans-serif", direction: "rtl", background: "#fafafa", minHeight: "100vh", padding: "32px" }}>
      {/* زر تسجيل الدخول أو تسجيل الخروج */}
      <div style={{ position: "fixed", top: 18, right: 32, zIndex: 2001 }}>
        {!user && (
          <button
            onClick={() => setShowLogin(true)}
            style={{
              fontSize: 18,
              background: "#16a085",
              color: "#fff",
              border: "none",
              borderRadius: 12,
              padding: "8px 20px",
              cursor: "pointer"
            }}
          >
            تسجيل الدخول
          </button>
        )}
        {user && (
          <button
            onClick={async () => {
              await supabase.auth.signOut();
              setUser(null);
            }}
            style={{
              fontSize: 15,
              background: "#fa5a7d",
              color: "#fff",
              border: "none",
              borderRadius: 12,
              padding: "6px 14px",
              cursor: "pointer",
              marginRight: 8
            }}
          >
            تسجيل الخروج
          </button>
        )}
      </div>
      {/* نافذة تسجيل الدخول */}
      {showLogin && <Login onClose={() => setShowLogin(false)} />}
      <h1 style={{ textAlign: "center", marginBottom: 24 }}>لوحة تقارير الطلبات</h1>
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 20, gap: 12 }}>
        <label>
          <span>عدد الزيارات:</span>
          <input
            type="number"
            min={0}
            value={visits}
            onChange={e => setVisits(Number(e.target.value))}
            style={{ margin: "0 8px", padding: "6px 16px", fontSize: 16, width: 110, borderRadius: 8, border: "1px solid #ddd" }}
          />
        </label>
        {/* إظهار زر رفع الملف فقط للمستخدم المسجل */}
        {user && (
          <input type="file" accept=".csv,.xlsx,.xls" onChange={handleFileUpload} style={{ marginRight: 16 }} />
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 28 }}>
        <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: "18px 32px", fontSize: 30, color: "#16a085", fontWeight: "bold", margin: "0 8px" }}>
          إجمالي المبيعات
          <div style={{ fontSize: 40 }}>{(summary.totalSales || 0).toLocaleString()} ريال</div>
        </div>
      </div>

      {/* رسم بياني لطريقة الدفع */}
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 40 }}>
        <div style={{ background: "white", borderRadius: 20, boxShadow: "0 2px 8px #eee", padding: 24 }}>
          <h3 style={{ textAlign: "center" }}>طريقة الدفع</h3>
          <div style={{ minHeight: 270 }}>
            {paymentData.length === 0 ? (
              <div style={{ color: "#777", fontSize: 19 }}>لا توجد بيانات</div>
            ) : (
              <svg width={320} height={270}>
                <foreignObject width="100%" height="100%">
                  <div style={{ display: "flex", justifyContent: "center" }}>
                    <div>
                      {/* يمكنك استخدام مكتبة رسم دائرية مثل recharts، هنا placeholder */}
                      {paymentData.map((d, i) => (
                        <div key={d.name} style={{ color: COLORS[i % COLORS.length], fontSize: 18 }}>
                          {d.name}: {d.value}
                        </div>
                      ))}
                    </div>
                  </div>
                </foreignObject>
              </svg>
            )}
          </div>
        </div>
      </div>

      {/* جدول وسيلة الشحن */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 600, margin: "40px auto" }}>
        <h3 style={{ textAlign: "center" }}>جدول أنواع الشحن وعدد الطلبات</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>وسيلة الشحن</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {shippingTable.map((ship, idx) => (
              <tr key={ship.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{ship.name}</td>
                <td>{ship.value}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* جدول أكثر المنتجات مبيعًا */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 600, margin: "40px auto" }}>
        <h3 style={{ textAlign: "center" }}>أكثر 10 منتجات طلبًا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المنتج</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topProducts.map((prod, idx) => (
              <tr key={prod.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{idx + 1}</td>
                <td>{prod.name}</td>
                <td>{prod.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* جدول أكثر المدن طلبًا */}
      <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24, maxWidth: 400, margin: "40px auto" }}>
        <h3 style={{ textAlign: "center" }}>أكثر 5 مدن طلبًا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المدينة</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topRegions.map((city, idx) => (
              <tr key={city.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{idx + 1}</td>
                <td>{city.name}</td>
                <td>{city.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* شاشة تحميل فقط أثناء التحميل */}
      {(loading || uploading) && (
        <div style={{
          position: "fixed", top: 0, left: 0, width: "100vw", height: "100vh",
          background: "rgba(255,255,255,0.6)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 9999
        }}>
          <div style={{ fontSize: 28, color: "#049790" }}>جاري التحميل...</div>
        </div>
      )}
    </div>
  );
}

export default App;
